(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({
    viewport: { width: 600, height: 1600 }
  });

  try {
    await page.goto(`file:///app/output/Worlds-Most-Valuable-Companies-2025-infographic.html`, {
      waitUntil: 'networkidle',
      timeout: 30000
    });

    await page.waitForTimeout(3000);

    const posterContainer = await page.$('.poster-container');
    if (posterContainer) {
      const screenshot = await posterContainer.screenshot({
        type: 'png',
        path: '/app/output/final_poster.png',
        fullPage: true
      });
      console.log('Poster generated at /app/output/final_poster.png');
    } else {
      console.log('Taking full page screenshot...');
      await page.screenshot({
        type: 'png',
        path: '/app/output/final_poster.png',
        fullPage: true
      });
    }
  } catch (error) {
    console.error('Error:', error.message);
    await page.screenshot({ type: 'png', path: '/app/output/error_screenshot.png' });
  } finally {
    await browser.close();
  }
})();

